rating_migration_backtest<-function(records,predicted_transition_matrices,states,state_contract,design,uncertainty,weights=NULL,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);if(d$target$conditioning!='origin_state') .cr_error('VALIDATION_TARGET','Migration must condition on origin_state');rows<-.vb_records(records,d);levels<-.ex_ids(states,'states');contract<-.ex_object(state_contract,'state_contract');k<-length(levels);n<-length(rows);for(key in c('scale_id','scale_version','reference')).vb_string(contract[[key]],key);known<-.cr_data_date(contract$known_at,'state contract known_at');if(any(vapply(rows,function(r)known>.cr_data_date(r$as_of,'as_of'),logical(1)))) .cr_error('VALIDATION_LOOKAHEAD','State definition must precede forecasts');keys<-c('default_states','cure_states','exit_states','absorbing_states');groups<-setNames(lapply(keys,function(key).ex_ids(contract[[key]],key,empty=key!='default_states')),keys)
 if(any(vapply(groups,function(v)length(setdiff(v,levels))>0,logical(1)))||length(intersect(groups$default_states,groups$cure_states))||length(intersect(groups$default_states,groups$exit_states))||length(intersect(groups$cure_states,groups$exit_states))) .cr_error('VALIDATION_STATES','Known disjoint default/cure/exit and absorbing states required')
 raw<-predicted_transition_matrices;if(is.matrix(raw))matrices<-rep(list(.cr_numeric(raw,'transition matrix')),n)else if(is.list(raw)&&length(raw)&&all(vapply(raw,is.matrix,logical(1))))matrices<-lapply(raw,function(m).cr_numeric(m,'transition matrix'))else if(is.array(raw)&&length(dim(raw))==3L)matrices<-lapply(seq_len(dim(raw)[1]),function(i)matrix(raw[i,,],dim(raw)[2],dim(raw)[3]))else if(is.list(raw)&&length(raw)&&is.list(raw[[1]])&&length(raw[[1]])&&is.list(raw[[1]][[1]]))matrices<-lapply(raw,function(m).ex_matrix(m,'transition matrix'))else matrices<-rep(list(.ex_matrix(raw,'transition matrix')),n)
 if(length(matrices)!=n||any(vapply(matrices,function(m)!identical(dim(m),c(k,k))||any(!is.finite(m))||any(m<0|m>1)||any(abs(rowSums(m)-1)>1e-12),logical(1)))) .cr_error('VALIDATION_TRANSITIONS','Aligned row-stochastic transition matrices required')
 for(state in groups$absorbing_states){j<-match(state,levels);if(any(vapply(matrices,function(m)!identical(as.numeric(m[j,]),as.numeric(diag(k)[j,])),logical(1)))) .cr_error('VALIDATION_ABSORPTION','Absorbing rows must be exactly identity')};w<-if(is.null(weights))rep(1,n)else .vb_vec(weights,'weights',TRUE);if(length(w)!=n||any(w<0)||!is.finite(sum(w))) .cr_error('VALIDATION_WEIGHT','Aligned finite nonnegative weights required');origin<-destination<-rep(1L,n);eligible<-rep(1,n);exclusions<-list()
 for(i in seq_along(rows)){row<-rows[[i]];if(!identical(row$scale_id,contract$scale_id)||!identical(row$scale_version,contract$scale_version)||!(row$origin_state%in%levels)) .cr_error('VALIDATION_STATES','Matching scale/version and known origin required');origin[i]<-match(row$origin_state,levels);reason<-.vb_observed(row,d);status<-row$observation_status;if(!(status%in%c('OBSERVED','CENSORED'))) .cr_error('VALIDATION_OBSERVATION','Observed or censored endpoint required');if(is.null(reason)&&status=='CENSORED')reason<-'CENSORED_ENDPOINT'
 if(is.null(reason)){state<-row$destination_state;if(!(state%in%levels)) .cr_error('VALIDATION_STATES','Unknown destination state');at<-.cr_data_date(row$state_observed_at,'state_observed_at');end<-.cr_data_date(row$horizon_end,'horizon_end');if(at<.cr_data_date(row$as_of,'as_of')||at>.cr_data_date(row$outcome_known_at,'outcome_known_at')) .cr_error('VALIDATION_LOOKAHEAD','Endpoint date incompatible with observation/knowledge');if(at!=end&&!(at<end&&state%in%groups$absorbing_states))reason<-'ENDPOINT_STATE_NOT_OBSERVED'else if(row$origin_state%in%groups$absorbing_states&&state!=row$origin_state)reason<-'OBSERVED_ABSORBING_STATE_VIOLATION'else destination[i]<-match(state,levels)}
 if(!is.null(reason)){eligible[i]<-0;exclusions[[length(exclusions)+1L]]<-list(prediction_id=row$prediction_id,reason=reason)}
 }
 probabilities<-if(n)do.call(rbind,lapply(seq_len(n),function(i)matrices[[i]][origin[i],]))else matrix(numeric(),0,k);truth<-if(n)diag(k)[destination,,drop=FALSE]else matrix(numeric(),0,k);loss<-rowSums((probabilities-truth)^2);prob_observed<-if(n)probabilities[cbind(seq_len(n),destination)]else numeric();draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level)
 calculate<-function(draw){weight<-w*eligible*draw;total<-sum(weight);if(!is.finite(total)) .cr_error('VALIDATION_NUMERICAL','Resampled weight total exceeds finite range');counts<-expected<-rawcounts<-matrix(0,k,k);origins<-list();for(i in seq_len(n))if(weight[i]>0){counts[origin[i],destination[i]]<-counts[origin[i],destination[i]]+weight[i];expected[origin[i],]<-expected[origin[i],]+weight[i]*probabilities[i,];rawcounts[origin[i],destination[i]]<-rawcounts[origin[i],destination[i]]+draw[i]}
 score<-function(mask){mass<-weight*mask;total<-sum(mass);active<-mass>0;if(total==0)return(list(brier=NULL,log_loss=NULL,log_loss_status='NOT_APPLICABLE',applicability='NOT_APPLICABLE',reason='EMPTY_WEIGHTED_ORIGIN'));infinite<-any(prob_observed[active]==0);ll<-if(infinite)NULL else -sum((mass[active]/total)*log(prob_observed[active]));list(brier=sum((mass/total)*loss),log_loss=ll,log_loss_status=if(infinite)'INFINITE'else'FINITE',applicability='APPLICABLE',reason=NULL)}
 for(j in seq_along(levels)){mass<-sum(counts[j,]);origins[[j]]<-c(list(origin_state=levels[j],n=sum(origin==j&weight>0),weight_sum=mass,observed_counts=as.list(counts[j,]),unweighted_counts=as.list(rawcounts[j,]),expected_counts=as.list(expected[j,]),observed_probabilities=if(mass>0)as.list(counts[j,]/mass)else NULL,expected_probabilities=if(mass>0)as.list(expected[j,]/mass)else NULL,residuals=if(mass>0)as.list(counts[j,]-expected[j,])else NULL),score(origin==j))};overall<-score(rep(TRUE,n));overall$weight_sum<-total;overall['destination_default_share']<-list(if(total>0)sum(counts[,match(groups$default_states,levels),drop=FALSE])/total else NULL);list(overall=overall,by_origin=origins,states=as.list(levels),multiclass_brier_convention='SUM_OF_K_SQUARED_PROBABILITY_ERRORS_RANGE_0_TO_2',observed_weighted_counts=.ex_rows(counts),expected_weighted_counts=.ex_rows(expected))
 }
 metrics<-calculate(rep(1,n));samples<-if(is.null(draws))NULL else lapply(draws,function(draw){m<-calculate(draw);flat<-m$overall[c('brier','log_loss','destination_default_share')];for(origin_row in m$by_origin)for(j in seq_along(levels))flat[paste0('transition/',origin_row$origin_state,'/',levels[j])]<-list(if(is.null(origin_row$observed_probabilities))NULL else origin_row$observed_probabilities[[j]]);flat})
 diagnostics<-list(state_contract=contract,transition_fingerprint=.cr_hash(lapply(matrices,.ex_rows)),weights=as.list(w),endpoint_policy='EXACT_HORIZON_OBSERVATION_OR_EARLIER_DECLARED_ABSORBING_STATE',default_cure_exit_separate=TRUE,no_inferred_censored_self_transition=TRUE,log_loss_boundary_policy='EXACT_NULL_PLUS_INFINITE',observed_absorption_violations=sum(vapply(exclusions,function(e)e$reason=='OBSERVED_ABSORBING_STATE_VIOLATION',logical(1))));result<-.vb_result('rating_migration_backtest',metrics,d,rows,exclusions,.vb_bands(samples,confidence_level),context,diagnostics,'migration_validation');if(is.null(metrics$overall$brier)){result$value$applicability<-'NOT_APPLICABLE';result$value$reason<-'NO_POSITIVE_WEIGHT_OBSERVED_TRANSITIONS'};result
}
